// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
import { Triangle } from "@remotion/shapes";

// Load Google Font at module level
const { fontFamily: antonFamily } = loadAnton();



export type StopBeingBottleneckProps = Record<string, any>;

const StopBeingBottleneck: React.FC<StopBeingBottleneckProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "STOP BEING\nTHE BOTTLE NECK",
  primarySignColor = "#FFCC00", // Industrial Warning Yellow
  secondarySignColor = "#000000",
  textColor = "#FFFFFF",
  flashSpeed = 6,
  signScale = 1.2,
  textScale = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety logic for transparent background parser
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Sign Animation Springs & Interpolations
  const signScaleAnim = spring({
    frame,
    fps,
    config: { damping: 10, stiffness: 120 },
  });

  const signRotate = spring({
    frame,
    fps,
    config: { damping: 10, stiffness: 100 },
  });

  // A subtle slam rotation as the sign enters
  const rotation = interpolate(signRotate, [0, 1], [-15, 0]);

  // Continuous subtle scale for the entire scene to keep it alive
  const continuousScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.05]
  );

  // Text Animation Interpolations
  const textOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const textY = interpolate(frame, [10, 25], [40, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Flashing Logic: Inverts primary and secondary colors rapidly
  const isFlashOn =
    flashSpeed === 0 || frame < 15
      ? true
      : Math.floor((frame - 15) / (fps / flashSpeed)) % 2 === 0;

  const activeFill = isFlashOn ? primarySignColor : secondarySignColor;
  const activeStroke = isFlashOn ? secondarySignColor : primarySignColor;
  const activeExclamation = isFlashOn ? secondarySignColor : primarySignColor;

  // Responsive Dimensions
  const triangleLength = width * 0.6;
  const strokeThickness = Math.floor(triangleLength * 0.08);
  const cornerRounding = triangleLength * 0.05;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: antonFamily,
      }}
    >
      <div
        style={{
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${
            signScaleAnim * signScale * continuousScale
          }) rotate(${rotation}deg)`,
          filter: isFlashOn
            ? `drop-shadow(0px 0px 50px ${primarySignColor}66)`
            : "none",
          transition: "none",
        }}
      >
        <Triangle
          length={triangleLength}
          direction="up"
          fill={activeFill}
          stroke={activeStroke}
          strokeWidth={strokeThickness}
          cornerRadius={cornerRounding}
          strokeLinejoin="round"
        />
        {/* The Exclamation Mark */}
        <div
          style={{
            position: "absolute",
            top: "58%", // Optically centers in the visual centroid of the triangle
            left: "50%",
            transform: "translate(-50%, -50%)",
            fontSize: triangleLength * 0.45,
            color: activeExclamation,
            lineHeight: 1,
            transition: "none",
          }}
        >
          !
        </div>
      </div>

      <div
        style={{
          marginTop: height * 0.05,
          fontSize: width * 0.12 * textScale,
          color: textColor,
          textAlign: "center",
          opacity: textOpacity,
          transform: `translateY(${textY}px) scale(${continuousScale})`,
          width: "90%",
          whiteSpace: "pre-wrap",
          wordWrap: "break-word",
          lineHeight: 1.1,
          textTransform: "uppercase",
          textShadow: `0px ${width * 0.008}px ${width * 0.02}px rgba(0, 0, 0, 0.6)`,
          transition: "none",
        }}
      >
        {text}
      </div>
    </AbsoluteFill>
  );
};

export default StopBeingBottleneck;